class SaleItem extends DataClass implements Insertable<SaleItem> {
  final String id;
  final String businessId;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String? createdBy;
  final String saleId;
  final String productId;
  final String? variantId;
  final String? imeiUnitId;

  /// Snapshot of the product name at sale time.
  final String description;
  final String? unitId;

  /// Quantity in the unit sold (e.g. 2 cartons).
  final int unitQty;

  /// Quantity in base units (e.g. 48 pcs). Stock moves by this.
  final int qty;

  /// Price per sold unit (per carton when sold by carton).
  final Money unitPrice;
  final Money discount;

  /// unitQty × unitPrice − discount.
  final Money lineTotal;

  /// lineTotal minus this line's share of the invoice discount.
  final Money netAmount;

  /// This line's share of invoice tax.
  final Money taxAmount;

  /// Average cost per base unit at sale time (spec 8.1).
  final Money unitCostSnapshot;

  /// Exact COGS posted for this line (avoids rounding drift on returns).
  final Money costTotal;
  const SaleItem({
    required this.id,
    required this.businessId,
    required this.createdAt,
    required this.updatedAt,
    this.createdBy,
    required this.saleId,
    required this.productId,
    this.variantId,
    this.imeiUnitId,
    required this.description,
    this.unitId,
    required this.unitQty,
    required this.qty,
    required this.unitPrice,
    required this.discount,
    required this.lineTotal,
    required this.netAmount,
    required this.taxAmount,
    required this.unitCostSnapshot,
    required this.costTotal,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['business_id'] = Variable<String>(businessId);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || createdBy != null) {
      map['created_by'] = Variable<String>(createdBy);
    }
    map['sale_id'] = Variable<String>(saleId);
    map['product_id'] = Variable<String>(productId);
    if (!nullToAbsent || variantId != null) {
      map['variant_id'] = Variable<String>(variantId);
    }
    if (!nullToAbsent || imeiUnitId != null) {
      map['imei_unit_id'] = Variable<String>(imeiUnitId);
    }
    map['description'] = Variable<String>(description);
    if (!nullToAbsent || unitId != null) {
      map['unit_id'] = Variable<String>(unitId);
    }
    map['unit_qty'] = Variable<int>(unitQty);
    map['qty'] = Variable<int>(qty);
    {
      map['unit_price'] = Variable<int>(
        $SaleItemsTable.$converterunitPrice.toSql(unitPrice),
      );
    }
    {
      map['discount'] = Variable<int>(
        $SaleItemsTable.$converterdiscount.toSql(discount),
      );
    }
    {
      map['line_total'] = Variable<int>(
        $SaleItemsTable.$converterlineTotal.toSql(lineTotal),
      );
    }
    {
      map['net_amount'] = Variable<int>(
        $SaleItemsTable.$converternetAmount.toSql(netAmount),
      );
    }
    {
      map['tax_amount'] = Variable<int>(
        $SaleItemsTable.$convertertaxAmount.toSql(taxAmount),
      );
    }
    {
      map['unit_cost_snapshot'] = Variable<int>(
        $SaleItemsTable.$converterunitCostSnapshot.toSql(unitCostSnapshot),
      );
    }
    {
      map['cost_total'] = Variable<int>(
        $SaleItemsTable.$convertercostTotal.toSql(costTotal),
      );
    }
    return map;
  }

