class Purchase extends DataClass implements Insertable<Purchase> {
  final String id;
  final String businessId;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String? createdBy;
  final int billSeq;
  final String billNo;
  final String? supplierBillNo;
  final String? partyId;
  final DateTime date;
  final Money subtotal;
  final Money discount;

  /// Freight and purchase tax paid to the supplier; added to inventory cost.
  final Money extraCost;
  final Money total;
  final Money paid;
  final PaymentMethod paidMethod;
  final Money due;
  final DocStatus status;
  final String? reversesId;
  final String? billPhotoPath;
  final String? note;
  const Purchase({
    required this.id,
    required this.businessId,
    required this.createdAt,
    required this.updatedAt,
    this.createdBy,
    required this.billSeq,
    required this.billNo,
    this.supplierBillNo,
    this.partyId,
    required this.date,
    required this.subtotal,
    required this.discount,
    required this.extraCost,
    required this.total,
    required this.paid,
    required this.paidMethod,
    required this.due,
    required this.status,
    this.reversesId,
    this.billPhotoPath,
    this.note,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['business_id'] = Variable<String>(businessId);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || createdBy != null) {
      map['created_by'] = Variable<String>(createdBy);
    }
    map['bill_seq'] = Variable<int>(billSeq);
    map['bill_no'] = Variable<String>(billNo);
    if (!nullToAbsent || supplierBillNo != null) {
      map['supplier_bill_no'] = Variable<String>(supplierBillNo);
    }
    if (!nullToAbsent || partyId != null) {
      map['party_id'] = Variable<String>(partyId);
    }
    map['date'] = Variable<DateTime>(date);
    {
      map['subtotal'] = Variable<int>(
        $PurchasesTable.$convertersubtotal.toSql(subtotal),
      );
    }
    {
      map['discount'] = Variable<int>(
        $PurchasesTable.$converterdiscount.toSql(discount),
      );
    }
    {
      map['extra_cost'] = Variable<int>(
        $PurchasesTable.$converterextraCost.toSql(extraCost),
      );
    }
    {
      map['total'] = Variable<int>(
        $PurchasesTable.$convertertotal.toSql(total),
      );
    }
    {
      map['paid'] = Variable<int>($PurchasesTable.$converterpaid.toSql(paid));
    }
    {
      map['paid_method'] = Variable<String>(
        $PurchasesTable.$converterpaidMethod.toSql(paidMethod),
      );
    }
    {
      map['due'] = Variable<int>($PurchasesTable.$converterdue.toSql(due));
    }
    {
      map['status'] = Variable<String>(
        $PurchasesTable.$converterstatus.toSql(status),
      );
    }
    if (!nullToAbsent || reversesId != null) {
      map['reverses_id'] = Variable<String>(reversesId);
    }
    if (!nullToAbsent || billPhotoPath != null) {
      map['bill_photo_path'] = Variable<String>(billPhotoPath);
    }
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    return map;
  }

  PurchasesCompanion toCompanion(bool nullToAbsent) {
    return PurchasesCompanion(
      id: Value(id),
      businessId: Value(businessId),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      createdBy: createdBy == null && nullToAbsent
          ? const Value.absent()
          : Value(createdBy),
      billSeq: Value(billSeq),
      billNo: Value(billNo),
      supplierBillNo: supplierBillNo == null && nullToAbsent
