          : Value(partyId),
      date: Value(date),
      subtotal: Value(subtotal),
      discount: Value(discount),
      extraCost: Value(extraCost),
      total: Value(total),
      paid: Value(paid),
      paidMethod: Value(paidMethod),
      due: Value(due),
      status: Value(status),
      reversesId: reversesId == null && nullToAbsent
          ? const Value.absent()
          : Value(reversesId),
      billPhotoPath: billPhotoPath == null && nullToAbsent
          ? const Value.absent()
          : Value(billPhotoPath),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
    );
  }

