class PurchaseItem extends DataClass implements Insertable<PurchaseItem> {
  final String id;
  final String businessId;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String? createdBy;
  final String purchaseId;
  final String productId;
  final String? variantId;
  final String description;
  final String? unitId;
  final int unitQty;
  final int qty;

  /// Cost per purchased unit as entered.
  final Money unitCost;
  final Money lineTotal;

  /// Inventory value added: lineTotal − discount share + extra cost share.
  final Money netCost;
  const PurchaseItem({
    required this.id,
    required this.businessId,
    required this.createdAt,
    required this.updatedAt,
    this.createdBy,
    required this.purchaseId,
    required this.productId,
    this.variantId,
    required this.description,
    this.unitId,
    required this.unitQty,
    required this.qty,
    required this.unitCost,
    required this.lineTotal,
    required this.netCost,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['business_id'] = Variable<String>(businessId);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || createdBy != null) {
      map['created_by'] = Variable<String>(createdBy);
    }
    map['purchase_id'] = Variable<String>(purchaseId);
    map['product_id'] = Variable<String>(productId);
    if (!nullToAbsent || variantId != null) {
      map['variant_id'] = Variable<String>(variantId);
    }
    map['description'] = Variable<String>(description);
    if (!nullToAbsent || unitId != null) {
      map['unit_id'] = Variable<String>(unitId);
    }
    map['unit_qty'] = Variable<int>(unitQty);
    map['qty'] = Variable<int>(qty);
    {
      map['unit_cost'] = Variable<int>(
        $PurchaseItemsTable.$converterunitCost.toSql(unitCost),
      );
    }
    {
      map['line_total'] = Variable<int>(
        $PurchaseItemsTable.$converterlineTotal.toSql(lineTotal),
      );
    }
    {
      map['net_cost'] = Variable<int>(
        $PurchaseItemsTable.$converternetCost.toSql(netCost),
      );
    }
    return map;
  }

  PurchaseItemsCompanion toCompanion(bool nullToAbsent) {
    return PurchaseItemsCompanion(
      id: Value(id),
      businessId: Value(businessId),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      createdBy: createdBy == null && nullToAbsent
          ? const Value.absent()
          : Value(createdBy),
      purchaseId: Value(purchaseId),
      productId: Value(productId),
