      unitId: unitId == null && nullToAbsent
          ? const Value.absent()
          : Value(unitId),
      unitQty: Value(unitQty),
      qty: Value(qty),
      unitCost: Value(unitCost),
      lineTotal: Value(lineTotal),
      netCost: Value(netCost),
    );
  }

