class RepairPart extends DataClass implements Insertable<RepairPart> {
  final String id;
  final String businessId;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String? createdBy;
  final String jobId;
  final String productId;
  final String? variantId;
  final RepairPartAction action;
  final int qty;

  /// Cost per unit at issue time.
  final Money unitCost;

  /// Total cost moved (qty × avg cost, rounded).
  final Money costTotal;

  /// What the customer is charged for this part (informational).
  final Money charge;
  const RepairPart({
    required this.id,
    required this.businessId,
    required this.createdAt,
    required this.updatedAt,
    this.createdBy,
    required this.jobId,
    required this.productId,
