    required this.partyId,
    this.guarantorName,
    this.guarantorPhone,
    required this.cashPrice,
    required this.markup,
    required this.total,
    required this.downPayment,
    required this.installments,
    required this.frequency,
    required this.startDate,
    required this.status,
  });
