    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['business_id'] = Variable<String>(businessId);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || createdBy != null) {
      map['created_by'] = Variable<String>(createdBy);
    }
    map['sale_id'] = Variable<String>(saleId);
    map['party_id'] = Variable<String>(partyId);
    if (!nullToAbsent || guarantorName != null) {
      map['guarantor_name'] = Variable<String>(guarantorName);
    }
    if (!nullToAbsent || guarantorPhone != null) {
      map['guarantor_phone'] = Variable<String>(guarantorPhone);
    }
    {
      map['cash_price'] = Variable<int>(
        $QistPlansTable.$convertercashPrice.toSql(cashPrice),
      );
    }
    {
      map['markup'] = Variable<int>(
        $QistPlansTable.$convertermarkup.toSql(markup),
      );
    }
    {
      map['total'] = Variable<int>(
        $QistPlansTable.$convertertotal.toSql(total),
      );
    }
    {
      map['down_payment'] = Variable<int>(
        $QistPlansTable.$converterdownPayment.toSql(downPayment),
      );
    }
    map['installments'] = Variable<int>(installments);
    {
      map['frequency'] = Variable<String>(
        $QistPlansTable.$converterfrequency.toSql(frequency),
      );
    }
    map['start_date'] = Variable<DateTime>(startDate);
    {
      map['status'] = Variable<String>(
        $QistPlansTable.$converterstatus.toSql(status),
      );
    }
    return map;
  }

